    query_converted = _ffi.cast("const void *", query)
    out_result = _ffi.new("MeosArray *")
    _lib.rtree_search(rtree_converted, op_converted, query_converted, out_result)
    _check_error()
    return out_result if out_result != _ffi.NULL else None


